def solve(N, M, A, G):
    def chmax(dp, a, value):
        if dp[a] < value:
            dp[a] = value

    dp = [0] * N
    dp[0] = 1
    for v in sorted(range(N), key=lambda i: A[i]):
        for a in G[v]:
            if A[v] <= A[a]:
                chmax(dp, a, dp[v] + 1)

    max_score = dp[N-1]
    return max_score
